# This script is used to move the trajectory files from the image folders in the external hard drive (vorg) to the
# local folder

# I use it separately for each fluorophore used in the experiment as py4bleaching needs to be run separately on each
# differently labelled molecule set

# It also creates a new folder structure

# Output folder structure generated by this script:
#
# imagejresults-647/                     (output_folder)
# └── 647/
#     ├── 0mins_bleach/sHsp/
#     │   ├── red3colour_all1.csv
#     │   ├── red3colour_all2.csv
#     │   └── ... (one per .csv found in the matching input folder)
#     │
#     ├── 15mins_bleach/sHsp/
#     │   └── red3colour_all<n>.csv
#     │
#     ├── 60mins_bleach/sHsp/
#     │   └── red3colour_all<n>.csv
#     │
#     └── 120mins_bleach/sHsp/
#         └── red3colour_all<n>.csv
#

library(fs)

# change these for experiment
input_folder <- "Z:/Chaperone_subgroup/NicolaA/Fluc complexes/20260305/"

output_folder <- "imagejresults-647/"

if (!dir_exists(output_folder)) {
  dir_create(output_folder)
}

# can change based on proteins in experiment

aBc3D_0mins   <- "red3colour_all"
aBc3D_15mins  <- "red3colour_all"
aBc3D_60mins  <- "red3colour_all"
aBc3D_120mins <- "red3colour_all"

# change these for the experiment you're using
folders <- list(
  "0mins_bleach/20260305_100028_795/AF647 photobleach/Trajectories/ALL/sHsp/"   = list(new_folder = "647/0mins_bleach/sHsp/",   filetype = aBc3D_0mins),
  "15mins_bleach/20260305_131229_212/AF647 photobleach/Trajectories/ALL/sHsp/"  = list(new_folder = "647/15mins_bleach/sHsp/",  filetype = aBc3D_15mins),
  "60mins_bleach/20260305_110751_653/AF647 photobleach/Trajectories/ALL/sHsp/"  = list(new_folder = "647/60mins_bleach/sHsp/",  filetype = aBc3D_60mins),
  "120mins_bleach/20260305_121240_380/AF647 photobleach/Trajectories/ALL/sHsp/" = list(new_folder = "647/120mins_bleach/sHsp/", filetype = aBc3D_120mins)
  
)

for (old_folder in names(folders)) {
  
  new_folder <- folders[[old_folder]]$new_folder
  filetype   <- folders[[old_folder]]$filetype
  
  old_path <- file.path(input_folder, old_folder)
  
  old_files <- list.files(old_path, pattern = "\\.csv$")
  
  new_path <- file.path(output_folder, new_folder)
  
  if (!dir_exists(new_path)) {
    dir_create(new_path)
  }
  
  for (x in seq_along(old_files)) {
    file_copy(
      path = file.path(old_path, old_files[x]),
      new_path = file.path(new_path, paste0(filetype, x, ".csv")),
      overwrite = TRUE
    )
  }
}